-- mod-advanced-professions: книги эскизов.
--
-- ФАЙЛ СОБРАН ГЕНЕРАТОРОМ `tools/gen-synergy-books.py` - правится он.
--
-- Книг: 3160, блок с 191000.
--
-- ЗАМЫСЕЛ (решение владельца 2026-09-13). Вещь, которая раньше просто падала с
-- босса, теперь собирается из ДВУХ находок: заготовки и книги эскиза. Босс
-- роняет либо одно, либо другое; по отдельности не работает ни то, ни другое.
-- Плюс материалы на саму доводку.
--
-- Поэтому книга нужна КАЖДОМУ эскизу, а не только геройскому: список верстака
-- показывает лишь изученное, а угадать упорядоченный набор из четырёх камней
-- нельзя (§5.6). Пока книги не было, эскиз находили только случайно.
--
-- ВИД отличает книгу от чертежа основы: чертёж - свёрнутый пергамент (1102),
-- книга эскиза - переплёт (1103). Одного взгляда в сумку хватает, чтобы
-- понять, чего не хватает до сборки.
--
-- ЧТЕНИЕ - те же пять секунд и тот же порядок, что у чертежа (§5.4.4.1):
-- заказ в очередь мастера, шелест страницы, книга тратится только когда
-- чтение дошло до конца.
--
-- Дизайн: .claude/advanced-professions/DESIGN.md §5.6, §5.4.4.1.

-- --------------------------------------------------------------------------
-- 1. Повторный прогон
-- --------------------------------------------------------------------------
UPDATE `ap_synergy` SET `teach_item` = 0
WHERE `teach_item` BETWEEN 191000 AND 199999;

-- Снос идёт ПО УГЛУ, а не по имени. Раньше в условии стояло `name LIKE`, и
-- переименование книг («эскиз» -> «эскиз») оставило бы все прежние строки
-- сиротами: новая миграция их бы не узнала. Угол 191000-199999 принадлежит
-- книгам целиком, чужого здесь нет.
DELETE t FROM `item_template` t
WHERE t.`entry` BETWEEN 191000 AND 199999
  AND NOT EXISTS (SELECT 1 FROM `ap_synergy` s WHERE s.`teach_item` = t.`entry`);

-- --------------------------------------------------------------------------
-- 2. Кому какая книга
-- --------------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS `ap_synbook`;
CREATE TEMPORARY TABLE `ap_synbook` (
  `entry`   INT UNSIGNED PRIMARY KEY,
  `syn_id`  INT UNSIGNED NOT NULL,
  `name`    VARCHAR(255) NOT NULL,
  `quality` TINYINT UNSIGNED NOT NULL,
  `buy`     INT UNSIGNED NOT NULL,
  `sell`    INT UNSIGNED NOT NULL,
  KEY (`syn_id`)
);

