-- --------------------------------------------------------------------------
-- 3. Сами книги
-- --------------------------------------------------------------------------
-- `spellid_1` = 483 («Обучение») нужен ровно затем, чтобы клиент показал у
-- предмета кнопку «Использовать»: сам каст модуль отменяет и ведёт своё
-- пятисекундное чтение.
INSERT IGNORE INTO `item_template`
  (`entry`, `class`, `subclass`, `SoundOverrideSubclass`, `name`, `displayid`,
   `Quality`, `Flags`, `BuyCount`, `BuyPrice`, `SellPrice`, `InventoryType`,
   `Stackable`, `MaxCount`, `Material`, `Sheath`, `RequiredLevel`,
   `ItemLevel`, `bonding`, `spellid_1`, `spelltrigger_1`, `spellcharges_1`)
SELECT b.`entry`, 9, 0, -1, b.`name`, 1103,
       b.`quality`, 0, 1, b.`buy`, b.`sell`,
       0, 1, 0, 8, 0, 0, 0, 0, 483, 0, -1
FROM `ap_synbook` b;

UPDATE `ap_synergy` s
JOIN `ap_synbook` b ON b.`syn_id` = s.`id`
SET s.`teach_item` = b.`entry`;

DROP TEMPORARY TABLE IF EXISTS `ap_synbook`;

-- Каталог меняется: у эскизов появились книги (§7, «Кэш каталога»).
UPDATE `ap_config` SET `value` = `value` + 1 WHERE `name` = 'catalog_version';
